-- Job #580 (Aran 2026-10-13): link every linkable missing seed clip in the two Welsh SANDBOXES (cym_nv2_for_eng, cym_sv2_for_eng)
-- to an EXISTING human take of the exact same text (whitespace and apostrophes normalised). No recording, no synthesis.
-- Plan from link-cym-sandbox-seed-clips-580-plan.sql (audit: job #576). Eligibility, re-asserted below against the live rows:
--   known   : a human English take (role known, language eng) from any course.
--   target1 : North Catrin (human_catrinlliar_cym_n / human_catrinv2_cym_n), South Dan (human_dan_cym_s), from any role;
--   target2 : North Aran (human_aran_cym_n / _2 / aranv3), South Eleri (human_eleri_cym_s), from any role;
--   or, for a target slot, an unnamed original (legacy_import) of the SAME slot from the SAME dialect's live course
--   (cym_n_for_eng for North, cym_s_for_eng for South). Never a North take on South or the other way round; never Aran on Catrin's slot.
-- Every linked file was HEAD-checked 200 on S3 at plan time and has a duration in course_audio.
-- Live cym_n/cym_s (seeds, legos, phrases, their course_audio), master canonical_seeds and every other sandbox
-- seed/LEGO/phrase are fingerprinted before and after and must not change. Dry run unless  -v finish=COMMIT .
-- Undo: link-cym-sandbox-seed-clips-580-undo.sql.
\set ON_ERROR_STOP on
\if :{?finish}
\else
  \set finish ROLLBACK
\endif
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL statement_timeout = '20min';
CREATE FUNCTION pg_temp.nz(t text) RETURNS text IMMUTABLE LANGUAGE sql AS $$
  SELECT btrim(regexp_replace(translate(coalesce(t,''), E'\u2019\u2018\u02BC\u0060\u00B4\u2032', ''''''''''''), '\s+', ' ', 'g')) $$;
CREATE TEMP TABLE links (seed_id uuid, course_code text, seed_number int, slot text, audio_id uuid, txt text, PRIMARY KEY (seed_id, slot));

SELECT count(*) AS locked_seeds FROM (SELECT 1 FROM course_seeds s WHERE s.id IN (SELECT seed_id FROM links) FOR UPDATE OF s) x;

CREATE FUNCTION pg_temp.fp() RETURNS TABLE(t text, n bigint, h text) LANGUAGE sql AS $$
  SELECT 'canonical_seeds (master)', count(*), md5(string_agg(md5(x::text), '' ORDER BY x::text)) FROM canonical_seeds x
  UNION ALL SELECT 'live '||x.course_code||' seeds', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_seeds x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'live '||x.course_code||' legos', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_legos x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'live '||x.course_code||' phrases', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_practice_phrases x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'live '||x.course_code||' audio', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_audio x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' legos', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_legos x WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' phrases', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_practice_phrases x WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' other seeds', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_seeds x
    WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') AND x.id NOT IN (SELECT seed_id FROM links) GROUP BY x.course_code
  UNION ALL SELECT 'linked audio rows', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_audio x WHERE x.id IN (SELECT audio_id FROM links)
$$;
CREATE TEMP TABLE pre AS SELECT * FROM pg_temp.fp();
SELECT 'BEFORE' k, * FROM pre ORDER BY t;

DO $$ BEGIN
  IF to_regclass('backup_cym_seed_clips_580') IS NOT NULL THEN RAISE EXCEPTION 'already applied'; END IF;
  IF (SELECT count(*) FROM links) <> 471 THEN RAISE EXCEPTION 'expected 471 links'; END IF;
  IF EXISTS (SELECT 1 FROM links WHERE course_code NOT IN ('cym_nv2_for_eng','cym_sv2_for_eng')) THEN RAISE EXCEPTION 'a write is outside the sandboxes'; END IF;
  -- the slot is still empty and the seed's text is still the text we matched
  IF (SELECT count(*) FROM links k JOIN course_seeds s ON s.id = k.seed_id AND s.course_code = k.course_code AND s.seed_number = k.seed_number
      WHERE CASE k.slot WHEN 'known' THEN s.known_audio_id IS NULL AND s.known_text = k.txt
                        WHEN 'target1' THEN s.target1_audio_id IS NULL AND s.target_text = k.txt
                        WHEN 'target2' THEN s.target2_audio_id IS NULL AND s.target_text = k.txt END) <> (SELECT count(*) FROM links) THEN
    RAISE EXCEPTION 'CHANGED UNDER US: a slot is no longer empty or the seed text changed — re-plan'; END IF;
  -- every take: human, alive, same text, right language/role, right dialect and voice
  IF (SELECT count(*) FROM links k JOIN course_audio a ON a.id = k.audio_id
      WHERE a.origin = 'human' AND coalesce(a.duration_ms, 0) > 0 AND coalesce(a.file_size_bytes, 2000) >= 2000 AND a.veracity_pass IS NOT FALSE
        AND pg_temp.nz(a.text) = pg_temp.nz(k.txt)
        AND CASE
          WHEN k.slot = 'known' THEN a.role = 'known' AND a.language = 'eng'
          WHEN a.language <> 'cym' OR a.role NOT IN ('target1','target2') THEN false
          WHEN k.course_code = 'cym_nv2_for_eng' AND k.slot = 'target1' THEN a.voice_id IN ('human_catrinlliar_cym_n','human_catrinv2_cym_n') OR (a.voice_id = 'legacy_import' AND a.role = 'target1' AND a.course_code = 'cym_n_for_eng')
          WHEN k.course_code = 'cym_nv2_for_eng' AND k.slot = 'target2' THEN a.voice_id IN ('human_aran_cym_n','human_aran_cym_n_2','human_aranv3_cym_n') OR (a.voice_id = 'legacy_import' AND a.role = 'target2' AND a.course_code = 'cym_n_for_eng')
          WHEN k.course_code = 'cym_sv2_for_eng' AND k.slot = 'target1' THEN a.voice_id = 'human_dan_cym_s' OR (a.voice_id = 'legacy_import' AND a.role = 'target1' AND a.course_code = 'cym_s_for_eng')
          WHEN k.course_code = 'cym_sv2_for_eng' AND k.slot = 'target2' THEN a.voice_id = 'human_eleri_cym_s' OR (a.voice_id = 'legacy_import' AND a.role = 'target2' AND a.course_code = 'cym_s_for_eng')
        END) <> (SELECT count(*) FROM links) THEN
    RAISE EXCEPTION 'a take is gone, synthetic, dead, a different text, or the wrong dialect/voice for its slot'; END IF;
END $$;

CREATE TABLE backup_cym_seed_clips_580 AS SELECT s.* FROM course_seeds s WHERE s.id IN (SELECT seed_id FROM links);
CREATE TABLE backup_cym_seed_clips_580_links AS SELECT * FROM links;
REVOKE ALL ON backup_cym_seed_clips_580, backup_cym_seed_clips_580_links FROM anon, authenticated;

SELECT c, 'sql:job-580 link-cym-sandbox-seed-clips', 'link-seed-audio', 'agent', 'claude-job-580-seed-clips',
       'agent (claude-job-580-seed-clips)', false, 'creator',
       jsonb_build_object('links', (SELECT jsonb_agg(jsonb_build_array(seed_number, slot, audio_id) ORDER BY seed_number, slot) FROM links WHERE course_code = c)),
       jsonb_build_object('ruling', 'Aran 2026-10-13 (job #580, audit #576): empty seed clip slots in the Welsh sandboxes point at an existing human take of the exact same text (whitespace/apostrophes normalised); Welsh slots only in the right dialect and cast voice, or an unnamed original of the same slot from the same dialect course. Nothing recorded or rendered.',
                          'backup', 'backup_cym_seed_clips_580')
FROM (VALUES ('cym_nv2_for_eng'), ('cym_sv2_for_eng')) v(c);
CREATE TEMP TABLE ev AS SELECT DISTINCT ON (course_code) course_code, id FROM content_edit_events WHERE detail->>'backup'='backup_cym_seed_clips_580' ORDER BY course_code, occurred_at DESC, id;

UPDATE course_seeds s SET
  known_audio_id   = coalesce(s.known_audio_id,   (SELECT audio_id FROM links k WHERE k.seed_id = s.id AND k.slot = 'known')),
  target1_audio_id = coalesce(s.target1_audio_id, (SELECT audio_id FROM links k WHERE k.seed_id = s.id AND k.slot = 'target1')),
  target2_audio_id = coalesce(s.target2_audio_id, (SELECT audio_id FROM links k WHERE k.seed_id = s.id AND k.slot = 'target2')),
  last_edit_event_id = ev.id
FROM ev WHERE ev.course_code = s.course_code AND s.id IN (SELECT seed_id FROM links);
SET CONSTRAINTS ALL IMMEDIATE;

CREATE TEMP TABLE post AS SELECT * FROM pg_temp.fp();
SELECT 'AFTER' k, * FROM post ORDER BY t;
DO $$ BEGIN
  IF EXISTS (SELECT * FROM pre EXCEPT SELECT * FROM post) OR EXISTS (SELECT * FROM post EXCEPT SELECT * FROM pre) THEN
    RAISE EXCEPTION 'CHECK FAILED: live Welsh, master canonical_seeds, the linked audio rows, or other sandbox seeds/LEGOs/phrases changed'; END IF;
  IF (SELECT count(*) FROM links k JOIN course_seeds s ON s.id = k.seed_id
      WHERE CASE k.slot WHEN 'known' THEN s.known_audio_id WHEN 'target1' THEN s.target1_audio_id ELSE s.target2_audio_id END = k.audio_id) <> (SELECT count(*) FROM links) THEN
    RAISE EXCEPTION 'CHECK FAILED: a slot does not hold its planned take'; END IF;
  IF EXISTS (SELECT 1 FROM backup_cym_seed_clips_580 b JOIN course_seeds s ON s.id = b.id
      WHERE (to_jsonb(b) - 'version' - 'updated_at' - 'last_edit_event_id' - 'known_audio_id' - 'target1_audio_id' - 'target2_audio_id')
         <> (to_jsonb(s) - 'version' - 'updated_at' - 'last_edit_event_id' - 'known_audio_id' - 'target1_audio_id' - 'target2_audio_id')
         OR (b.known_audio_id IS NOT NULL AND b.known_audio_id IS DISTINCT FROM s.known_audio_id)
         OR (b.target1_audio_id IS NOT NULL AND b.target1_audio_id IS DISTINCT FROM s.target1_audio_id)
         OR (b.target2_audio_id IS NOT NULL AND b.target2_audio_id IS DISTINCT FROM s.target2_audio_id)) THEN
    RAISE EXCEPTION 'CHECK FAILED: a linked seed changed beyond filling its empty slots'; END IF;
  RAISE NOTICE 'LINKED: % slots on % seeds', (SELECT count(*) FROM links), (SELECT count(DISTINCT seed_id) FROM links);
END $$;
SELECT k.course_code, k.slot, count(*) linked FROM links k GROUP BY 1,2 ORDER BY 1,2;
SELECT s.course_code, count(*) FILTER (WHERE s.known_audio_id IS NOT NULL AND s.target1_audio_id IS NOT NULL AND s.target2_audio_id IS NOT NULL) replayable_played, count(*) played
FROM course_seeds s JOIN (SELECT DISTINCT course_code, seed_number FROM course_running_order) ro USING (course_code, seed_number)
WHERE s.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') GROUP BY 1 ORDER BY 1;
SELECT 'finishing with' k, :'finish' v;
:finish;
